import com.dataflow.platform.mapper.FileRecordMapper;
import com.dataflow.platform.mapper.ImportTaskMapper;
import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Service;

@Service
public class ImportTaskService {
    private final ImportTaskMapper importTaskMapper;
    private final FileRecordMapper fileRecordMapper;

    public ImportTaskService(ImportTaskMapper importTaskMapper, FileRecordMapper fileRecordMapper) {
        this.importTaskMapper = importTaskMapper;
        this.fileRecordMapper = fileRecordMapper;
    }

    public ApiResponse<Map<String, Object>> create(TaskCreateRequest request, Long userId) {
        if (request == null || fileRecordMapper.findByFileKey(request.getFileKey()) == null) {
            return ApiResponse.error(400, "关联的文件不存在");
        }
        LocalDateTime now = LocalDateTime.now();
        ImportTask task = new ImportTask();
        task.setName(request.getName());
        task.setType(request.getType());
        task.setStatus("PENDING");
        task.setUserId(userId);
        task.setFileKey(request.getFileKey());
        task.setRecordCount(0);
        task.setCreatedAt(now);
        task.setUpdatedAt(now);
        importTaskMapper.insert(task);
        return ApiResponse.success("创建成功", creationPayload(task));
    }

    public List<Map<String, Object>> list(Long userId, String role) {
        List<ImportTask> tasks = "ADMIN".equals(role)
                ? importTaskMapper.findAll()
                : importTaskMapper.findByUserId(userId);
        return tasks.stream().map(this::detailPayload).toList();
    }

    public ApiResponse<Map<String, Object>> detail(Long id, Long userId, String role) {
        ImportTask task = importTaskMapper.findById(id);
        if (task == null || (!"ADMIN".equals(role) && !userId.equals(task.getUserId()))) {
            return ApiResponse.error(404, "任务不存在");
        }
        return ApiResponse.success(detailPayload(task));
    }

    private Map<String, Object> creationPayload(ImportTask task) {
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("id", task.getId());
        payload.put("name", task.getName());
        payload.put("type", task.getType());
        payload.put("status", task.getStatus());
        payload.put("fileKey", task.getFileKey());
        payload.put("createdAt", task.getCreatedAt());
        return payload;
    }

    private Map<String, Object> detailPayload(ImportTask task) {
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("id", task.getId());
        payload.put("name", task.getName());
        payload.put("type", task.getType());
        payload.put("status", task.getStatus());
        payload.put("fileKey", task.getFileKey());
        payload.put("recordCount", task.getRecordCount());
        payload.put("createdAt", task.getCreatedAt());
        payload.put("updatedAt", task.getUpdatedAt());
        return payload;
    }
}

package com.dataflow.platform.util;

import com.dataflow.platform.entity.User;
import com.dataflow.platform.mapper.UserMapper;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDateTime;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

@Component
public class DataInitializer implements CommandLineRunner {
    private final UserMapper userMapper;
    private final Path storageRoot;

    public DataInitializer(UserMapper userMapper,
                           @Value("${dataflow.storage.root}") String storageRoot) {
        this.userMapper = userMapper;
        this.storageRoot = Path.of(storageRoot).toAbsolutePath().normalize();
    }

    @Override
    public void run(String... args) throws Exception {
        if (userMapper.count() == 0) {
            LocalDateTime startupTime = LocalDateTime.now();
            insertUser("admin", "admin123", "ADMIN", startupTime);
            insertUser("user1", "user123", "USER", startupTime);
            insertUser("user2", "user456", "USER", startupTime);
        }

        Path templates = storageRoot.resolve("templates");
        Files.createDirectories(templates);
        Files.createDirectories(storageRoot.resolve("uploads/2"));
        Files.createDirectories(storageRoot.resolve("uploads/3"));
        createTemplate(templates.resolve("import_user.xlsx"),
                "username,email,phone\n张三,zhangsan@example.com,13800000001");
        createTemplate(templates.resolve("import_product.xlsx"),
                "product_name,price,category\n示例产品,99.00,电子产品");
        createTemplate(templates.resolve("import_order.xlsx"),
                "order_no,customer,amount\nORD001,张三,199.00");
    }

    private void insertUser(String username, String password, String role, LocalDateTime createdAt) {
        User user = new User();
        user.setUsername(username);
        user.setPassword(password);
        user.setRole(role);
        user.setCreatedAt(createdAt);
        userMapper.insert(user);
    }

    private void createTemplate(Path path, String content) throws Exception {
        if (Files.notExists(path)) {
            Files.writeString(path, content, StandardCharsets.UTF_8);
        }
    }
}

package com.dataflow.platform.util;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import java.nio.charset.StandardCharsets;
import java.util.Date;
import javax.crypto.SecretKey;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class JwtUtil {
    private final SecretKey signingKey;
    private final long expiration;

    public JwtUtil(@Value("${jwt.secret}") String secret,
                   @Value("${jwt.expiration}") long expiration) {
        this.signingKey = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
        this.expiration = expiration;
    }

    public String generateToken(Long userId, String username, String role) {
        Date issuedAt = new Date();
        Date expiresAt = new Date(issuedAt.getTime() + expiration);
        return Jwts.builder()
                .subject(username)
                .claim("userId", userId)
                .claim("username", username)
                .claim("role", role)
                .issuedAt(issuedAt)
                .expiration(expiresAt)
                .signWith(signingKey)
                .compact();
    }

    public Claims parseToken(String token) {
        return Jwts.parser()
                .verifyWith(signingKey)
                .build()
                .parseSignedClaims(token)
                .getPayload();
    }

    public boolean validateToken(String token) {
        try {
            parseToken(token);
            return true;
        } catch (RuntimeException ex) {
            return false;
        }
    }

    public Long getUserId(String token) {
        return getUserId(parseToken(token));
    }

    public Long getUserId(Claims claims) {
        Number value = claims.get("userId", Number.class);
        return value == null ? null : value.longValue();
    }

    public String getUsername(String token) {
        return parseToken(token).get("username", String.class);
    }

    public String getRole(String token) {
        return parseToken(token).get("role", String.class);
    }
}
